def is_sum_of_two_squares(n):
    for i in range(int(n**0.5) + 1):
        j2 = n - i*i
        j = int(j2**0.5)
        if j*j == j2:
            return True
    return False

def is_sum_of_two_triangulars(m):
    M = 8*m + 2
    for i in range(1, int(M**0.5) + 1, 2):
        j2 = M - i*i
        j = int(j2**0.5)
        if j*j == j2 and j % 2 == 1:
            return True
    return False

